package com.hbm.block.oilplant;
import com.hbm.hazard.HbmHazards;import com.hbm.block.ore.LegacyOreBlock;import com.mojang.serialization.MapCodec;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.server.level.ServerLevel;import net.minecraft.tags.FluidTags;import net.minecraft.util.RandomSource;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.level.storage.loot.LootParams;
/** Full BlockNTMFlower: all six originals, exact natural/bonemeal growth, soil and seed behavior. */
public final class OilFlowerBlock extends Block implements BonemealableBlock {
 public static final IntegerProperty META=IntegerProperty.create("legacy_meta",0,15);public static final List<String> NAMES=List.of("foxglove","tobacco","nightshade","weed","cd0","cd1");private static final MapCodec<OilFlowerBlock> CODEC=simpleCodec(p->new OilFlowerBlock());
 public OilFlowerBlock(){super(Properties.of().mapColor(MapColor.PLANT).strength(0).sound(SoundType.GRASS).noCollission().noOcclusion().randomTicks());registerDefaultState(stateDefinition.any().setValue(META,0));}@Override protected MapCodec<? extends Block> codec(){return CODEC;}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> builder){builder.add(META);}
 public static boolean soil(BlockState state){if(state.is(Blocks.GRASS_BLOCK)||state.is(Blocks.DIRT)||state.is(Blocks.FARMLAND))return true;String id=BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString();return id.equals("hbm:dirt_dead")||id.equals("hbm:dirt_oily");}public static boolean oily(BlockState state){String id=BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString();return id.equals("hbm:dirt_dead")||id.equals("hbm:dirt_oily");}
 public static boolean water(LevelReader level,BlockPos base){for(var side:Direction.Plane.HORIZONTAL)if(level.getFluidState(base.below().relative(side)).is(FluidTags.WATER))return true;return false;}
 @Override public BlockState getStateForPlacement(BlockPlaceContext context){var state=defaultBlockState().setValue(META,((OilPlantItem)context.getItemInHand().getItem()).metadata(context.getItemInHand()));return canSurvive(state,context.getLevel(),context.getClickedPos())?state:null;}
 @Override protected boolean canSurvive(BlockState state,LevelReader level,BlockPos pos){return soil(level.getBlockState(pos.below()));}@Override protected void neighborChanged(BlockState state,Level level,BlockPos pos,Block neighbor,BlockPos from,boolean moving){if(!canSurvive(state,level,pos)){dropResources(state,level,pos);level.setBlock(pos,Blocks.AIR.defaultBlockState(),2);}}
 @Override protected List<ItemStack> getDrops(BlockState state,LootParams.Builder params){int meta=state.getValue(META);return List.of(OilBotanyContent.flowerStack(meta==5?4:meta));}
 @Override public ItemStack getCloneItemStack(LevelReader level,BlockPos pos,BlockState state){return OilBotanyContent.flowerStack(state.getValue(META));}
 @Override protected void randomTick(BlockState state,ServerLevel level,BlockPos pos,RandomSource random){int meta=state.getValue(META)%6;if(meta!=3&&meta!=4&&meta!=5)return;if(isValidBonemealTarget(level,pos,state)&&isBonemealSuccess(level,random,pos,state)&&random.nextInt(3)==0)performBonemeal(level,random,pos,state);}
 @Override public boolean isValidBonemealTarget(LevelReader level,BlockPos pos,BlockState state){int meta=state.getValue(META);if((meta==4||meta==5)&&!water(level,pos))return false;return(meta!=3&&meta!=5)||level.isEmptyBlock(pos.above());}
 @Override public boolean isBonemealSuccess(Level level,RandomSource random,BlockPos pos,BlockState state){int meta=state.getValue(META);return(meta!=3&&meta!=4&&meta!=5)||random.nextFloat()<.33F;}
 @Override public void performBonemeal(ServerLevel level,RandomSource random,BlockPos pos,BlockState state){int meta=state.getValue(META);if(meta==3){if(oily(level.getBlockState(pos.below()))){var dead=BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.parse("hbm:plant_dead")).defaultBlockState().setValue(LegacyOreBlock.LEGACY_META,0);level.setBlock(pos,dead,3);}else OilTallPlantBlock.place(level,pos,0);return;}if(meta==4){level.setBlock(pos,defaultBlockState().setValue(META,5),3);return;}if(meta==5){OilTallPlantBlock.place(level,pos,1);return;}popResource(level,pos,OilBotanyContent.flowerStack(meta));}
}
